#!/usr/bin/env python3
"""Minimal, reproducible eval runner (standard library only).

Usage:
  python runner.py --config configs/example.json --data data/example.jsonl \
                   --out results/example.jsonl [--dry-run] [--limit N]

Each line of --data is a JSON object with at least {"id": ..., "prompt": ...}.
Each line written to --out is a JSON object with the item id, the full request,
the raw response text, the config and its hash, and a timestamp.

Re-running with the same --out skips ids already present, so a crashed run can
be resumed and a results file is never partially overwritten.
"""
import argparse
import hashlib
import json
import os
import sys
import time
import urllib.error
import urllib.request


def load_jsonl(path):
    items = []
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                items.append(json.loads(line))
            except json.JSONDecodeError as e:
                sys.exit(f"{path}:{n}: bad JSON ({e})")
    return items


def config_hash(cfg):
    canon = json.dumps(cfg, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(canon).hexdigest()[:12]


def existing_ids(path):
    if not os.path.exists(path):
        return set()
    return {rec["id"] for rec in load_jsonl(path) if "id" in rec}


class DryRunClient:
    """Returns a deterministic fake response. For testing the pipeline."""

    def complete(self, messages, cfg):
        last = messages[-1]["content"]
        return "[dry-run] " + last[:60].replace("\n", " ")


class OpenAICompatibleClient:
    """Works with any endpoint speaking the OpenAI chat-completions format."""

    def __init__(self, base_url, api_key_env):
        self.base_url = base_url.rstrip("/")
        self.key = os.environ.get(api_key_env)
        if not self.key:
            sys.exit(f"Environment variable {api_key_env} is not set.")

    def complete(self, messages, cfg):
        body = {
            "model": cfg["model"],
            "messages": messages,
            "temperature": cfg.get("temperature", 0),
            "max_tokens": cfg.get("max_tokens", 512),
        }
        req = urllib.request.Request(
            self.base_url + "/chat/completions",
            data=json.dumps(body).encode(),
            headers={
                "Authorization": f"Bearer {self.key}",
                "Content-Type": "application/json",
            },
        )
        with urllib.request.urlopen(req, timeout=cfg.get("timeout_s", 120)) as r:
            data = json.load(r)
        return data["choices"][0]["message"]["content"]


def make_client(cfg, dry_run):
    if dry_run:
        return DryRunClient()
    provider = cfg.get("provider", "openai-compatible")
    if provider == "openai-compatible":
        return OpenAICompatibleClient(cfg["base_url"], cfg.get("api_key_env", "OPENAI_API_KEY"))
    sys.exit(f"Unknown provider: {provider}")


def build_messages(item, cfg):
    msgs = []
    system = item.get("system") or cfg.get("system")
    if system:
        msgs.append({"role": "system", "content": system})
    msgs.append({"role": "user", "content": item["prompt"]})
    return msgs


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--config", required=True)
    ap.add_argument("--data", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--limit", type=int, default=None, help="only run the first N items")
    ap.add_argument("--retries", type=int, default=3)
    ap.add_argument("--sleep", type=float, default=0.0, help="seconds between requests")
    args = ap.parse_args()

    with open(args.config, encoding="utf-8") as f:
        cfg = json.load(f)
    chash = config_hash(cfg)

    items = load_jsonl(args.data)
    if args.limit:
        items = items[: args.limit]
    done = existing_ids(args.out)
    todo = [it for it in items if it["id"] not in done]
    print(f"config {chash} | {len(items)} items | {len(done)} already done | {len(todo)} to run"
          + (" | DRY RUN" if args.dry_run else ""), file=sys.stderr)

    client = make_client(cfg, args.dry_run)
    os.makedirs(os.path.dirname(args.out) or ".", exist_ok=True)

    failures = 0
    with open(args.out, "a", encoding="utf-8") as out:
        for i, item in enumerate(todo, 1):
            messages = build_messages(item, cfg)
            response, error = None, None
            for attempt in range(1, args.retries + 1):
                try:
                    response = client.complete(messages, cfg)
                    break
                except (urllib.error.URLError, urllib.error.HTTPError, KeyError, TimeoutError) as e:
                    error = f"{type(e).__name__}: {e}"
                    time.sleep(min(2 ** attempt, 30))
            rec = {
                "id": item["id"],
                "config_hash": chash,
                "config": cfg,
                "messages": messages,
                "response": response,
                "error": None if response is not None else error,
                "dry_run": args.dry_run,
                "ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            }
            out.write(json.dumps(rec, ensure_ascii=False) + "\n")
            out.flush()
            if response is None:
                failures += 1
            if i % 10 == 0 or i == len(todo):
                print(f"  {i}/{len(todo)} done, {failures} failed", file=sys.stderr)
            if args.sleep:
                time.sleep(args.sleep)

    print(f"wrote {len(todo)} records to {args.out} ({failures} failures)", file=sys.stderr)
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())

